// The GRC platform's 'Call webhook' step sends {event, workflow, entity, record}. Personal data fields are already removed.
const src = $('Finding webhook').first().json;
const b = src.body || src;
const r = b.record || {};
const order = ['Low', 'Medium', 'High', 'Critical'];
const min = $('Settings').first().json.minimum_severity || 'High';
if (order.indexOf(r.severity) < order.indexOf(min)) return [];          // below the threshold: send nothing
const link = $('Settings').first().json.grc_url + '/#/e/' + (b.entity || 'finding') + '/' + r.id;
return [{ json: { text: `GRC ${r.severity} finding ${r.code}: ${r.title}
Status: ${r.status}. Due: ${r.due_date || 'not set'}.
${link}` } }];
